{
  "case_id": "CUS-SC010-D1",
  "dimensions": {
    "PS": {
      "score": 2,
      "rationale": "Answer X groups \"A 2.1; B 4.3; C 5.2\" under P01 and keeps \"D 7.1\" separate as a harm-avoidance limit, names legitimate purposes and limiting effects, and cites only supplied passages."
    },
    "CAL": {
      "score": 2,
      "rationale": "It is appropriately calibrated, stating that \"None of these passages cleanly fit P04 or P09\" and that the \"dominant mechanism is still paternalism\" rather than forcing a fit."
    },
    "CC": {
      "score": 2,
      "rationale": "It states both the legitimate purposes (\"Reduce confusion, prevent alarm, support adherence\") and the limiting effects (\"Denies patients their own data and one-sidedly frames medication decisions\"), including the near P04 counterpoint for B."
    }
  },
  "critical_failures": [],
